-- Mathematics Mock 3 (Mock Test 30). Exclusive, like the Mock 2s: it lives only in the
-- database and is shown only to accounts listed in mock_access. Run once in the SQL Editor.

insert into public.mocks (id, title, minutes, total, is_public, questions)
values ('math3', 'Mathematics Mock 3', 60, 30, false,
$json$[{"q": "A right circular cone has a slant height of 13 cm and a curved surface area of 65π cm^{2}.\nFind the volume of the cone, in cm^{3}.\nCone: curved surface area = πrl, volume = 1/3 πr^{2}h, where l is the slant height.", "options": ["100π/3", "60π", "65π", "260π/3", "100π", "325π/3", "130π", "300π"], "answer": 4, "topic": "M5 Geometry", "marks": 5, "image": "images/math3-q1.png", "alt": "A cone with slant height 13 cm.", "solution": "Answer E: 100π cm³", "solutionImage": "solutions/m3-q01.jpg"}, {"q": "A car uses 6.5 litres of fuel for every 100 km. Fuel costs 250 tenge per litre.\nWhat is the cost of the fuel for a journey of 360 km, in tenge?", "options": ["585", "1 625", "2 340", "2 500", "4 680", "5 000", "5 400", "5 850"], "answer": 7, "topic": "M1 Units", "marks": 3, "solution": "Answer H: 5 850 tenge", "solutionImage": "solutions/m3-q02.jpg"}, {"q": "A, B, C and D lie on a circle with centre O, and AC is a diameter. The chords AC and BD meet at X.\nAngle ACB = 34° and angle CAD = 48°.\nFind angle AXB.", "options": ["34°", "48°", "56°", "62°", "76°", "82°", "90°", "98°"], "answer": 5, "topic": "M5 Geometry", "marks": 8, "image": "images/math3-q3.png", "alt": "Circle with centre O, diameter AC, chords meeting at X, angle ACB 34 degrees and angle CAD 48 degrees.", "solution": "Answer F: 82°", "solutionImage": "solutions/m3-q03.jpg"}, {"q": "Given that (5 + √3)/(2 − √3) = a + b√3, where a and b are integers, find a + b.", "options": ["13", "17", "20", "23", "27", "33", "39", "47"], "answer": 2, "topic": "M2 Number", "marks": 4, "solution": "Answer C: 20", "solutionImage": "solutions/m3-q04.jpg"}, {"q": "Write 2.5 m^{2} in cm^{2}.", "options": ["0.00025", "0.025", "25", "250", "2 500", "25 000", "250 000", "2 500 000"], "answer": 5, "topic": "M1 Units", "marks": 1, "solution": "Answer F: 25 000 cm²", "solutionImage": "solutions/m3-q05.jpg"}, {"q": "Two runners start together from the same point on a circular track of length 400 m and run in opposite directions. One runs at 5 m/s and the other at 4 m/s.\nHow many times do they meet in the first 10 minutes, not counting the start?", "options": ["1", "6", "7", "12", "13", "14", "27", "54"], "answer": 4, "topic": "M3 Ratio and proportion", "marks": 6, "solution": "Answer E: 13", "solutionImage": "solutions/m3-q06.jpg"}, {"q": "Simplify (8x^{6}y^{−3})^{2/3}/(4x^{2}y)^{−1/2}, where x > 0 and y > 0.", "options": ["2x^{3}y^{−5/2}", "8x^{3}y^{−3/2}", "2x^{5}y^{−3/2}", "8x^{5}y^{−5/2}", "4x^{5}y^{−3/2}", "8x^{4}y^{−3/2}", "8x^{5}y^{−3/2}", "16x^{5}y^{−1/2}"], "answer": 6, "topic": "M4 Algebra", "marks": 5, "solution": "Answer G: 8x⁵y^(−3/2)", "solutionImage": "solutions/m3-q07.jpg"}, {"q": "ABCD is a square of side 12 cm. E is the midpoint of BC, and F is the point on CD with DF : FC = 1 : 2.\nThe lines AE and BF meet at G. Find the area of the shaded quadrilateral GECF, in cm^{2}.", "options": ["39", "40", "42", "45", "48", "54", "60", "72"], "answer": 0, "topic": "M5 Geometry", "marks": 10, "image": "images/math3-q8.png", "alt": "Square ABCD of side 12 cm with E the midpoint of BC, F on CD, lines AE and BF meeting at G, and quadrilateral GECF shaded.", "solution": "Answer A: 39 cm²", "solutionImage": "solutions/m3-q08.jpg"}, {"q": "Rice is sold in three packs. Pack A: 750 g for 1 350 tenge. Pack B: 1.2 kg for 2 040 tenge. Pack C: 400 g for 760 tenge.\nWhich pack is the best value, and what is its price per kilogram?", "options": ["Pack A, 1 800 tenge/kg", "Pack A, 1 350 tenge/kg", "Pack B, 1 700 tenge/kg", "Pack B, 2 040 tenge/kg", "Pack C, 1 900 tenge/kg", "Pack C, 1 520 tenge/kg", "Pack B, 1 600 tenge/kg", "Pack A, 1 700 tenge/kg"], "answer": 2, "topic": "M1 Units", "marks": 2, "solution": "Answer C: Pack B, 1 700 tenge/kg", "solutionImage": "solutions/m3-q09.jpg"}, {"q": "A bag contains red and blue counters in the ratio 5 : 3. After 12 red counters are removed and 4 blue counters are added, the numbers of red and blue counters are equal.\nHow many red counters were in the bag at the start?", "options": ["20", "24", "30", "32", "36", "40", "45", "48"], "answer": 5, "topic": "M3 Ratio and proportion", "marks": 4, "solution": "Answer F: 40", "solutionImage": "solutions/m3-q10.jpg"}, {"q": "Find the sum of all the solutions of 9^{x} − 4 × 3^{x + 1} + 27 = 0.", "options": ["1", "2", "3", "4", "6", "9", "12", "27"], "answer": 2, "topic": "M4 Algebra", "marks": 7, "solution": "Answer C: 3", "solutionImage": "solutions/m3-q11.jpg"}, {"q": "A rectangular floor measures 360 cm by 504 cm. It is covered exactly, without cutting, by identical square tiles whose side is a whole number of centimetres, as large as possible.\nHow many tiles are needed?", "options": ["5", "7", "12", "24", "35", "70", "72", "140"], "answer": 4, "topic": "M2 Number", "marks": 3, "solution": "Answer E: 35", "solutionImage": "solutions/m3-q12.jpg"}, {"q": "How many integers from 1 to 1000 inclusive can be written in the form a^{2} − b^{2}, where a and b are integers with a ≥ 0 and b ≥ 0?", "options": ["250", "300", "333", "500", "600", "667", "700", "750"], "answer": 7, "topic": "M2 Number", "marks": 12, "solution": "Answer H: 750", "solutionImage": "solutions/m3-q13.jpg"}, {"q": "The speed of a car, v m/s, at time t seconds is v = t^{2} for 0 ≤ t ≤ 4, as shown.\nUse 4 trapezia of equal width to estimate the distance travelled in the first 4 seconds, in metres.", "options": ["14", "16", "64/3", "22", "24", "30", "32", "64"], "answer": 3, "topic": "M4 Algebra", "marks": 5, "image": "images/math3-q14.png", "alt": "Graph of v = t squared from t = 0 to 4, with dashed lines at t = 2, 3 and 4.", "solution": "Answer D: 22 m", "solutionImage": "solutions/m3-q14.jpg"}, {"q": "In the diagram, AB is parallel to DE. Angle BAC = 40° and angle EDC = 65°.\nFind angle ACD.", "options": ["65°", "75°", "95°", "105°", "115°", "125°", "140°", "155°"], "answer": 3, "topic": "M5 Geometry", "marks": 4, "image": "images/math3-q15.png", "alt": "Parallel lines AB and DE with a bent line A to C to D; angle BAC 40 degrees and angle EDC 65 degrees.", "solution": "Answer D: 105°", "solutionImage": "solutions/m3-q15.jpg"}, {"q": "Given that x + 1/x = 3, find the value of x^{5} + 1/x^{5}.", "options": ["18", "47", "105", "118", "123", "126", "129", "243"], "answer": 4, "topic": "M4 Algebra", "marks": 9, "solution": "Answer E: 123", "solutionImage": "solutions/m3-q16.jpg"}, {"q": "The period of a pendulum is T = 2π√(L/g). Make g the subject.", "options": ["g = 4π^{2}L/T^{2}", "g = 2πL/T^{2}", "g = 4π^{2}T^{2}/L", "g = T^{2}/(4π^{2}L)", "g = L/(4π^{2}T^{2})", "g = 4π^{2}L^{2}/T^{2}", "g = 4πL/T^{2}", "g = 2π^{2}L/T^{2}"], "answer": 0, "topic": "M4 Algebra", "marks": 2, "solution": "Answer A: g = 4π²L/T²", "solutionImage": "solutions/m3-q17.jpg"}, {"q": "How many three-digit positive integers have digits that add up to 6?", "options": ["20", "21", "24", "27", "28", "30", "36", "45"], "answer": 1, "topic": "M2 Number", "marks": 6, "solution": "Answer B: 21", "solutionImage": "solutions/m3-q18.jpg"}, {"q": "A model of a boat is made to a scale of 1 : 50. The hull of the real boat has a volume of 25 m^{3}.\nWhat is the volume of the model's hull, in cm^{3}?", "options": ["4", "10", "40", "200", "500", "2 000", "10 000", "500 000"], "answer": 3, "topic": "M3 Ratio and proportion", "marks": 4, "solution": "Answer D: 200 cm³", "solutionImage": "solutions/m3-q19.jpg"}, {"q": "A circle has centre (3, 4) and passes through the origin O. P is the point on the circle diametrically opposite O.\nThe tangent to the circle at P meets the x-axis at S and the y-axis at T.\nFind the area of triangle OST.", "options": ["25", "50", "625/12", "75", "625/8", "100", "625/6", "625/3"], "answer": 6, "topic": "M5 Geometry", "marks": 11, "image": "images/math3-q20.png", "alt": "Circle with centre (3, 4) through the origin O; the tangent at P meets the axes at S and T.", "solution": "Answer G: 625/6", "solutionImage": "solutions/m3-q20.jpg"}, {"q": "The braking distance d m of a car is directly proportional to the square of its speed v km/h. When v = 40, d = 12.\nFind v when d = 27.", "options": ["54", "60", "72", "80", "90", "108", "120", "135"], "answer": 1, "topic": "M3 Ratio and proportion", "marks": 3, "solution": "Answer B: 60 km/h", "solutionImage": "solutions/m3-q21.jpg"}, {"q": "A trader sells two phones for 60 000 tenge each. On one phone the trader makes a profit of 20% of its cost price; on the other, a loss of 20% of its cost price.\nWhat is the overall result, as a percentage of the total cost price?", "options": ["a profit of 4%", "a profit of 2%", "no profit or loss", "a loss of 1%", "a loss of 2%", "a loss of 3%", "a loss of 4%", "a loss of 5%"], "answer": 6, "topic": "M3 Ratio and proportion", "marks": 5, "solution": "Answer G: a loss of 4%", "solutionImage": "solutions/m3-q22.jpg"}, {"q": "A driver travels 240 km at a constant speed of v km/h. If the speed were 20 km/h higher, the journey would take 1 hour less.\nFind v.", "options": ["60", "64", "72", "80", "90", "100", "120", "240"], "answer": 0, "topic": "M4 Algebra", "marks": 7, "solution": "Answer A: v = 60", "solutionImage": "solutions/m3-q23.jpg"}, {"q": "Which of these numbers is the third smallest?", "options": ["5/8", "0.63", "62.4%", "7/11", "2/3", "19/30"], "answer": 1, "topic": "M2 Number", "marks": 4, "solution": "Answer B: 0.63", "solutionImage": "solutions/m3-q24.jpg"}, {"q": "A running track is made of two straight sections, each 100 m long, and two semicircular ends, as shown. The total length of the track is 400 m.\nFind the area enclosed by the track, in m^{2}.", "options": ["10 000/π", "20 000/π", "30 000/π", "40 000/π", "50 000/π", "60 000/π", "80 000/π", "100 000/π"], "answer": 2, "topic": "M5 Geometry", "marks": 6, "image": "images/math3-q25.png", "alt": "Running track: two straight 100 m sides joined by semicircular ends.", "solution": "Answer C: 30 000/π m²", "solutionImage": "solutions/m3-q25.jpg"}, {"q": "The number of fish in a lake is modelled by Pₙ₊₁ = 1.1Pₙ − 500, where P₀ = 20 000.\nFind P₂.", "options": ["20 500", "21 000", "21 500", "22 000", "22 150", "22 650", "23 100", "23 150"], "answer": 7, "topic": "M3 Ratio and proportion", "marks": 3, "solution": "Answer H: 23 150", "solutionImage": "solutions/m3-q26.jpg"}, {"q": "The graph of y = x^{2} + bx + c crosses the x-axis at x = −1 and x = 5, as shown.\nFind the minimum value of y.", "options": ["−25", "−20", "−16", "−15", "−12", "−10", "−9", "−5"], "answer": 6, "topic": "M4 Algebra", "marks": 4, "image": "images/math3-q27.png", "alt": "Parabola y = x squared + bx + c crossing the x-axis at −1 and 5.", "solution": "Answer G: −9", "solutionImage": "solutions/m3-q27.jpg"}, {"q": "A runner covers 150 m, measured to the nearest 10 m, in 12 s, measured to the nearest second.\nFind the lower bound of the runner's average speed, in m/s.", "options": ["10.4", "11", "11.5", "11.6", "12", "12.4", "12.5", "13"], "answer": 3, "topic": "M2 Number", "marks": 5, "solution": "Answer D: 11.6 m/s", "solutionImage": "solutions/m3-q28.jpg"}, {"q": "OAB is a triangle with OA = a and OB = b. M is the midpoint of AB, and N is the point on OM with ON : NM = 2 : 1.\nFind the vector AN.", "options": ["(2a − b)/3", "(a + b)/3", "(b − a)/3", "(2b − a)/3", "(b − 2a)/2", "(a − 2b)/3", "(2b − 2a)/3", "(b − 2a)/3"], "answer": 7, "topic": "M5 Geometry", "marks": 4, "image": "images/math3-q29.png", "alt": "Triangle OAB with vectors a along OA and b along OB, M the midpoint of AB and N on OM.", "solution": "Answer H: (b − 2a)/3", "solutionImage": "solutions/m3-q29.jpg"}, {"q": "The graph of y = cos x for 0° ≤ x ≤ 360° is shown. Use the graph, and the fact that cos 60° = 1/2, to find all the solutions of 2 cos x + 1 = 0 for 0° ≤ x ≤ 360°.", "options": ["60° and 300°", "120° and 240°", "150° and 210°", "120° and 300°", "60° and 240°", "30° and 330°", "210° and 330°", "240° and 300°"], "answer": 1, "topic": "M4 Algebra", "marks": 5, "image": "images/math3-q30.png", "alt": "Graph of y = cos x from 0 to 360 degrees.", "solution": "Answer B: 120° and 240°", "solutionImage": "solutions/m3-q30.jpg"}]$json$::jsonb)
on conflict (id) do update set title = excluded.title, minutes = excluded.minutes,
  total = excluded.total, is_public = false, questions = excluded.questions;
